13	// ── Kill goes through procOS ─────────────────────────────────────────────────
14	
15	// Kill's only way to a signal is procOS.kill: that is what lets a test observe
16	// it, and what lets the guard stop a real one.
17	func TestKillSendsThroughProcOS(t *testing.T) {
18		fake := useFakeOS(t, 100, 99, "linux")
19	
20		if err := Kill("4242"); err != nil {
21			t.Fatalf("Kill(4242) = %v, want nil", err)
22		}
23		if len(fake.kills) != 1 || fake.kills[0] != 4242 {
24			t.Errorf("procOS.kill was called with %v, want [4242]", fake.kills)
25		}
26	}
27	
28	// ── The PID the kernel reads is not the PID the string says ──────────────────
29	
30	// The kernel reads the low 32 bits of the PID (pidfd_open, kill, OpenProcess
31	// all take 32 bits), so 1<<32+1 is PID 1 to it while an int comparison sees
32	// something else, and 4294967295 is kill(-1, SIGKILL): everything the user may
33	// signal. Kill and ProtectionOf share one parser that accepts only a canonical
34	// decimal in the int32 range (DEVDESK-708, criterion 4). Anything else is "not
35	// a process id", never a ProtectedError, and never reaches the OS.
36	func TestKillRefusesAPIDOutsideInt32OrNotCanonical(t *testing.T) {
37		const self, parent = 100, 99
38		cases := []struct {
39			name string
40			goos string
41			pid  string
42		}{
43			{"kill(-1) once truncated to 32 bits", "linux", "4294967295"},
44			{"PID 1 once truncated to 32 bits", "linux", "4294967297"},
45			{"one past int32", "linux", "2147483648"},
46			{"2^32, PID 0 once truncated", "linux", "4294967296"},
47			{"DevDesk itself once truncated", "linux", strconv.FormatInt(1<<32+int64(self), 10)},
48			{"the parent once truncated", "linux", strconv.FormatInt(1<<32+int64(parent), 10)},
49			{"the parent once truncated, far above", "linux", strconv.FormatInt(1<<40+int64(parent), 10)},
50			{"overflows even int64", "linux", "99999999999999999999"},
51			{"negative below int32", "linux", "-2147483649"},
52			{"explicit plus sign", "linux", "+5"},
53			{"leading zeros", "linux", "007"},
54			{"negative zero", "linux", "-0"},
55			{"leading space", "linux", " 5"},
56			{"trailing space", "linux", "5 "},
57			{"2^32 on Windows, the Idle process once truncated", "windows", "4294967296"},
58			{"2^32+4 on Windows, System once truncated", "windows", "4294967300"},
59			{"DevDesk itself once truncated on Windows", "windows", strconv.FormatInt(1<<32+int64(self), 10)},
60		}
61		for _, tc := range cases {
62			t.Run(tc.name, func(t *testing.T) {
63				fake := useFakeOS(t, self, parent, tc.goos)
64	
65				err := Kill(tc.pid)
66				if err == nil {
67					t.Errorf("Kill(%q) returned no error", tc.pid)
68				} else {
69					var perr *ProtectedError
70					if errors.As(err, &perr) {
71						t.Errorf("Kill(%q) = %v, a ProtectedError: the value is not a process id at all", tc.pid, err)
72					}
73					if !strings.Contains(err.Error(), "not a process id") {
74						t.Errorf("Kill(%q) = %q, want it to say %q", tc.pid, err.Error(), "not a process id")
75					}
76				}
77				if len(fake.kills) != 0 {
78					t.Errorf("procOS.kill was called with %v for %q", fake.kills, tc.pid)
79				}
80				if got := ProtectionOf(tc.pid); got != Unprotected {
81					t.Errorf("ProtectionOf(%q) = %v, want Unprotected", tc.pid, got)
82				}
83			})
84		}
85	}
