94		}
95		if err := Kill("2147483647"); err != nil {
96			t.Fatalf("Kill(2147483647) = %v, want nil", err)
97		}
98		if len(fake.kills) != 1 || fake.kills[0] != 2147483647 {
99			t.Errorf("procOS.kill was called with %v, want [2147483647]", fake.kills)
100		}
101	}
