103	// The Ports tab reads the failure with errors.Is (permission, already gone): the
104	// wrapping must keep the cause reachable.
105	func TestKillWrapsTheOSErrorSoTheUICanClassifyIt(t *testing.T) {
106		for _, cause := range []error{os.ErrPermission, os.ErrProcessDone} {
107			t.Run(cause.Error(), func(t *testing.T) {
108				fake := useFakeOS(t, 100, 99, "linux")
109				fake.killErr = cause
110	
111				err := Kill("4242")
112				if err == nil {
113					t.Fatal("Kill returned nil although the OS refused")
114				}
115				if !errors.Is(err, cause) {
116					t.Errorf("errors.Is(%v, %v) = false: the cause was not wrapped with %%w", err, cause)
117				}
118			})
119		}
120	}
