122	// ── The one real signal ──────────────────────────────────────────────────────
123	
124	const helperEnv = "DEVDESK_PORTS_HELPER"
125	
126	// TestHelperProcessSleeps is not a test: it is the body of the child process
127	// TestKillEndsARealChildProcess starts from this very binary. It does nothing
128	// unless the parent set the variable.
129	func TestHelperProcessSleeps(t *testing.T) {
130		if os.Getenv(helperEnv) != "1" {
131			t.Skip("helper process of TestKillEndsARealChildProcess")
132		}
133		time.Sleep(time.Minute)
134	}
135	
136	// TestKillEndsARealChildProcess is the only test of the package that sends a
137	// real signal, and it aims at a child it started itself: the test binary run
138	// again on the helper above. The child is always waited for, so it leaves
139	// neither a zombie nor an orphan.
140	func TestKillEndsARealChildProcess(t *testing.T) {
141		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcessSleeps$")
142		cmd.Env = append(os.Environ(), helperEnv+"=1")
143		if err := cmd.Start(); err != nil {
144			t.Fatalf("starting the helper process: %v", err)
145		}
146		pid := cmd.Process.Pid
147	
148		var waitErr error
149		done := make(chan struct{})
150		go func() {
151			waitErr = cmd.Wait()
152			close(done)
153		}()
154		t.Cleanup(func() {
155			_ = cmd.Process.Kill() // no-op error if Kill already ended it
156			select {
157			case <-done:
158			case <-time.After(10 * time.Second):
159				t.Errorf("the helper process %d did not exit and could not be waited for", pid)
160			}
161		})
162	
163		// Never signal anything that is not the child this test started.
164		if pid <= 1 || pid == os.Getpid() || pid == os.Getppid() {
165			t.Fatalf("the helper process has PID %d (self %d, parent %d): refusing to signal it", pid, os.Getpid(), os.Getppid())
166		}
167	
168		allowRealSignals(t)
169		if err := Kill(strconv.Itoa(pid)); err != nil {
170			t.Fatalf("Kill(%d) = %v, want nil", pid, err)
171		}
172	
173		select {
174		case <-done:
175		case <-time.After(10 * time.Second):
176			t.Fatalf("the helper process %d was still running 10 s after Kill", pid)
177		}
178		if waitErr == nil {
179			t.Error("the helper process exited successfully: it was not ended by the signal")
180		}
181		if cmd.ProcessState == nil || cmd.ProcessState.Success() {
182			t.Errorf("ProcessState = %v, want an unsuccessful exit", cmd.ProcessState)
183		}
184	}
