19	// --privileged`, and on Docker Desktop that is the VM's namespace — so the tab
20	// listed the VM's sockets and `K` killed the VM's processes. The correction is
21	// not "call Docker differently", it is "do not call Docker", and that is a
22	// property of the source rather than of a behaviour: a helper added here that
23	// shelled out would put the defect back without failing anything else.
24	func TestNothingHereRunsASubprocessOrTalksToDocker(t *testing.T) {
25		banned := map[string]string{
26			"os/exec": "a socket table read in this process is the whole point (D55)",
27			"github.com/anthnel/devdesk/internal/docker": "the Ports tab must work on a machine with no Docker",
28		}
29		entries, err := os.ReadDir(".")
30		if err != nil {
31			t.Fatalf("reading the package directory: %v", err)
32		}
33		fset := token.NewFileSet()
34		for _, e := range entries {
35			name := e.Name()
36			if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
37				continue
38			}
39			f, err := parser.ParseFile(fset, filepath.Join(".", name), nil, parser.SkipObjectResolution)
40			if err != nil {
41				t.Fatalf("parsing %s: %v", name, err)
42			}
43			for _, imp := range f.Imports {
44				path, _ := strconv.Unquote(imp.Path.Value)
45				if why, bad := banned[path]; bad {
46					t.Errorf("%s imports %q — %s", fset.Position(imp.Pos()), path, why)
47				}
48			}
49		}
50	}
