131	// ── Addresses ────────────────────────────────────────────────────────────────
132	
133	func TestAnIPv6AddressIsBracketed(t *testing.T) {
134		got := formatAddr(gnet.Addr{IP: "::", Port: 111}, 23)
135		if got != "[::]:111" {
136			t.Errorf("formatAddr = %q, want [::]:111 — unbracketed it is unreadable beside a port", got)
137		}
138	}
139	
140	// A listening socket has no peer, and the wildcard says which family it would
141	// have had one on. The AF_INET6 constant differs per platform, which is why all
142	// three are named rather than one compared against.
143	func TestASocketWithNoPeerShowsTheWildcardForItsFamily(t *testing.T) {
144		if got := formatAddr(gnet.Addr{}, 2); got != "0.0.0.0:*" {
145			t.Errorf("v4 peer = %q, want 0.0.0.0:*", got)
146		}
147		for _, family := range []uint32{23, 10, 30} { // windows, linux, darwin
148			if got := formatAddr(gnet.Addr{}, family); got != "[::]:*" {
149				t.Errorf("v6 peer (family %d) = %q, want [::]:*", family, got)
150			}
151		}
152	}
