157	// Zero is a process group on Unix and the idle process on Windows; a negative
158	// number is a whole group; an empty string is a row the system attributed to
159	// nobody, which is exactly the row a user is most likely to press K on.
160	func TestKillRefusesAnythingThatIsNotAProcessID(t *testing.T) {
161		fake := useFakeOS(t, 100, 99, "linux")
162		for _, pid := range []string{"", "0", "-1", "-812", "sshd", "8 12", "812.0"} {
163			if err := Kill(pid); err == nil {
