173	
174	// The invariants that matter are the ones a fixture cannot check: that the
175	// system answers at all, and that every row it produces is one the rest of the
176	// application can act on.
177	func TestTheMachinesOwnSocketTableSatisfiesTheRowInvariants(t *testing.T) {
178		sockets, err := List(context.Background(), false)
179		if err != nil {
180			t.Skipf("the socket table is not readable here: %v", err)
181		}
182		if len(sockets) == 0 {
183			t.Skip("no sockets to check")
184		}
185		for _, s := range sockets {
186			if s.PID != "" {
187				n, err := strconv.Atoi(s.PID)
188				if err != nil || n <= 0 {
189					t.Fatalf("PID %q is not something Kill would accept", s.PID)
190				}
191			}
192			if s.Process != "" && s.PID == "" {
193				t.Fatalf("a socket named a process (%q) with no PID to act on", s.Process)
194			}
195			if s.Protocol != "tcp" && s.Protocol != "udp" {
196				t.Fatalf("protocol = %q, want tcp or udp", s.Protocol)
197			}
198			if !strings.Contains(s.LocalAddr, ":") {
199				t.Fatalf("local address %q carries no port", s.LocalAddr)
200			}
201		}
202	}

