			return Identity{}, fmt.Errorf("process %d: %w", n, err)
		}
		return Identity{}, &UnverifiableError{PID: n, Cause: err}
	}
	switch judgeBirth(filetimeUnixNano(raw), int64(listed.raw), windowsBirthSlack) {
	case bornAfter:
		return Identity{}, &IdentityChangedError{PID: n}
	case bornAround:
		return Identity{}, &UnverifiableError{PID: n}
	}
	return Identity{identityKnown, raw}, nil
}

