	return Identity{identityKnown, raw}
}
func DeferredIdentityForTest(t time.Time) Identity {
	return Identity{identityDeferred, uint64(t.UnixNano())}
}

type UnverifiableError struct {
	PID   int
	Cause error
}

func (e *UnverifiableError) Error() string {
	return fmt.Sprintf("Cannot verify which process PID %d is — not stopped", e.PID)
}

type IdentityChangedError struct{ PID int }

func (e *IdentityChangedError) Error() string {
	return fmt.Sprintf("PID %d is no longer the process that was listed — not stopped", e.PID)
}

const windowsIdentityBudget = 100 * time.Millisecond
const windowsBirthSlack = 100 * time.Millisecond

func parseStartTicks(stat []byte) (uint64, error) {
	s := string(stat)
	i := strings.LastIndex(s, ")")
	if i < 0 {
		return 0, errors.New("no comm")
	}
	f := strings.Fields(s[i+1:])
	if len(f) < 20 {
		return 0, errors.New("short")
	}
	return strconv.ParseUint(f[19], 10, 64)
}
func timevalStamp(sec int64, usec int32) uint64 { return uint64(sec)*1e6 + uint64(usec) }
func filetimeUnixNano(raw uint64) int64        { return (int64(raw) - 116444736000000000) * 100 }

type birth int

const (
	bornBefore birth = iota
	bornAround
	bornAfter
)

func judgeBirth(c, l int64, slack time.Duration) birth {
	switch {
	case c <= l-int64(slack):
		return bornBefore
	case c > l:
		return bornAfter
	}
	return bornAround
}

func verdictAtSignal(pid int, want Identity, got uint64, readErr error) error {
	if readErr != nil {
		if errors.Is(readErr, os.ErrProcessDone) {
			return fmt.Errorf("process %d: %w", pid, os.ErrProcessDone)
		}
		return &UnverifiableError{PID: pid, Cause: readErr}
	}
	if got != want.raw {
		return &IdentityChangedError{PID: pid}
	}
	return nil
}

func ConfirmIdentity(pid string, listed Identity) (Identity, error) {
	n, ok := parsePID(pid)
	if !ok {
		return Identity{}, fmt.Errorf("not a process id: %q", pid)
	}
	switch listed.kind {
	case identityKnown:
		return listed, nil
	case identityNone:
		return Identity{}, &UnverifiableError{PID: n}
	}
	raw, err := procOS.identity(n)
	if err != nil {
		if errors.Is(err, os.ErrPermission) || errors.Is(err, os.ErrProcessDone) {
			return Identity{}, fmt.Errorf("process %d: %w", n, err)
		}
		return Identity{}, &UnverifiableError{PID: n, Cause: err}
	}
	switch judgeBirth(filetimeUnixNano(raw), int64(listed.raw), windowsBirthSlack) {
	case bornAfter:
		return Identity{}, &IdentityChangedError{PID: n}
	case bornAround:
		return Identity{}, &UnverifiableError{PID: n}
	}
	return Identity{identityKnown, raw}, nil
}

func readIdentity(pid int) (uint64, error) {
	b, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return 0, os.ErrProcessDone
		}
		return 0, err
	}
	return parseStartTicks(b)
}
