package ports

import (
	"slices"
	"strconv"
	"time"
)

func attachIdentities(sockets []Socket, listedAt time.Time) {
	var pids []int
	for _, s := range sockets {
		if n, err := strconv.Atoi(s.PID); err == nil && n > 0 && !slices.Contains(pids, n) {
			pids = append(pids, n)
		}
	}
	slices.Sort(pids)
	ids := map[string]Identity{}
	start := now()
	for _, pid := range pids {
		key := strconv.Itoa(pid)
		if goos == "windows" && now().Sub(start) >= windowsIdentityBudget {
			ids[key] = Identity{identityDeferred, uint64(listedAt.UnixNano())}
			continue
		}
		raw, err := procOS.identity(pid)
		if err != nil {
			continue
		}
		if goos == "windows" && judgeBirth(filetimeUnixNano(raw), listedAt.UnixNano(), windowsBirthSlack) != bornBefore {
			continue
		}
		ids[key] = Identity{identityKnown, raw}
	}
	for i := range sockets {
		sockets[i].Identity = ids[sockets[i].PID]
	}
}
